from __future__ import annotations

from typing import List, Optional

from pydantic import BaseModel, Field


class ApiUrls(BaseModel):
    main_api: str = Field(..., alias="main-api")
    main_binary_api: str = Field(..., alias="main-binary-api")
    tubus: str


class Android(BaseModel):
    build: str
    full_version: str
    url: str
    version: str


class Ios(BaseModel):
    build: str
    full_version: str
    url: str
    version: str


class LinuxX64(BaseModel):
    build: int
    full_version: str
    url: str
    version: str


class MacX64(BaseModel):
    build: int
    full_version: str
    url: str
    version: str


class MsiX32(BaseModel):
    build: int
    full_version: str
    url: str
    version: str


class WinX32(BaseModel):
    build: int
    full_version: str
    url: str
    version: str


class Apps(BaseModel):
    android: Android
    ios: Ios
    linux_x64: LinuxX64
    mac_x64: MacX64
    msi_x32: MsiX32
    win_x32: WinX32


class FilesParsing(BaseModel):
    main: str


class MiniappSharing(BaseModel):
    main: str


class Profile(BaseModel):
    main: str


class StickerpackSharing(BaseModel):
    main: str


class Survey(BaseModel):
    main: str


class VcsRoom(BaseModel):
    main: str


class BaseUrls(BaseModel):
    files_parsing: FilesParsing = Field(..., alias="files-parsing")
    miniapp_sharing: MiniappSharing = Field(..., alias="miniapp-sharing")
    profile: Profile
    stickerpack_sharing: StickerpackSharing = Field(..., alias="stickerpack-sharing")
    survey: Survey
    vcs_room: VcsRoom = Field(..., alias="vcs-room")


class Config(BaseModel):
    mail_android_app_urlscheme: str = Field(..., alias="mail-android-app-urlscheme")
    mail_ios_app_urlscheme: str = Field(..., alias="mail-ios-app-urlscheme")
    mail_mobile_url: str = Field(..., alias="mail-mobile-url")


class Mail(BaseModel):
    config: Config
    enabled: bool


class MiniApps(BaseModel):
    calendar_enabled: bool = Field(..., alias="calendar-enabled")
    mail: Mail
    mail_enabled: bool = Field(..., alias="mail-enabled")
    organization_structure_enabled: bool = Field(..., alias="organization-structure-enabled")
    tarm_calls_enabled: bool = Field(..., alias="tarm-calls-enabled")
    tarm_cloud_enabled: bool = Field(..., alias="tarm-cloud-enabled")
    tasks_enabled: bool = Field(..., alias="tasks-enabled")


class Calendar(BaseModel):
    external: bool
    mobile_create_event_url: str = Field(..., alias="mobile-create-event-url")
    mobile_url: str = Field(..., alias="mobile-url")
    needs_auth: bool
    url: str


class Web(BaseModel):
    external: bool


class Override(BaseModel):
    web: Web


class Mail1(BaseModel):
    external: bool
    mail_android_app_urlscheme: str = Field(..., alias="mail-android-app-urlscheme")
    mail_ios_app_urlscheme: str = Field(..., alias="mail-ios-app-urlscheme")
    mail_mobile_url: str = Field(..., alias="mail-mobile-url")
    needs_auth: bool
    override: Override
    url: str


class News(BaseModel):
    external: bool
    needs_auth: bool
    sn: str


class Orgstructure(BaseModel):
    external: bool
    needs_auth: bool
    url: str
    url_dark: str = Field(..., alias="url-dark")


class Polls(BaseModel):
    external: bool
    needs_auth: bool
    sn: str
    stamp: str


class TarmCalls(BaseModel):
    external: bool
    url: str


class TarmCloud(BaseModel):
    external: bool
    url: str


class Tasks(BaseModel):
    external: bool
    needs_auth: bool
    url: str


class Config1(BaseModel):
    calendar: Calendar
    mail: Mail1
    news: News
    orgstructure: Orgstructure
    polls: Polls
    tarm_calls: TarmCalls = Field(..., alias="tarm-calls")
    tarm_cloud: TarmCloud = Field(..., alias="tarm-cloud")
    tasks: Tasks


class Desktop(BaseModel):
    leftbar: List[str]


class Mobile(BaseModel):
    services: List[str]
    tabs: List[str]


class Disposition(BaseModel):
    desktop: Desktop
    mobile: Mobile


class Services(BaseModel):
    config: Config1
    disposition: Disposition


class TemplatesUrls(BaseModel):
    calendar: str
    di: str
    di_dark: str = Field(..., alias="di-dark")
    esia_auth: str = Field(..., alias="esia-auth")
    files: str
    files_parsing: str = Field(..., alias="files-parsing")
    mail: str
    miniapp_sharing: str = Field(..., alias="miniapp-sharing")
    mobile_calendar_create_event_url: str
    mobile_calendar_main_url: str
    profile: str
    stickerpack_sharing: str = Field(..., alias="stickerpack-sharing")
    tarm_calls: str = Field(..., alias="tarm-calls")
    tarm_cloud: str = Field(..., alias="tarm-cloud")
    tasks: str
    vcs_room: str = Field(..., alias="vcs-room")
    web_view: str = Field(..., alias="web-view")


class Config2(BaseModel):
    privacy_policy_url: str = Field(..., alias="privacy-policy-url")
    terms_of_use_url: str = Field(..., alias="terms-of-use-url")


class UserAgreement(BaseModel):
    config: Config2
    enabled: bool


class TarmConfig(BaseModel):
    allow_contacts_rename: bool = Field(..., alias="allow-contacts-rename")
    allow_self_avatar_change: bool = Field(..., alias="allow-self-avatar-change")
    allow_self_info_change: bool = Field(..., alias="allow-self-info-change")
    allow_self_name_change: bool = Field(..., alias="allow-self-name-change")
    allow_vcs_call_creation: bool = Field(..., alias="allow-vcs-call-creation")
    allow_vcs_webinar_creation: bool = Field(..., alias="allow-vcs-webinar-creation")
    antivirus_check_enabled: bool = Field(..., alias="antivirus-check-enabled")
    api_urls: ApiUrls = Field(..., alias="api-urls")
    api_version: int = Field(..., alias="api-version")
    apps: Apps
    attach_phone_enabled: bool = Field(..., alias="attach-phone-enabled")
    base_urls: BaseUrls = Field(..., alias="base-urls")
    call_link_v2_enabled: bool = Field(..., alias="call-link-v2-enabled")
    custom_miniapps: List = Field(..., alias="custom-miniapps")
    device_protection_required: bool = Field(..., alias="device-protection-required")
    discover_tab_enabled: bool = Field(..., alias="discover-tab-enabled")
    mini_apps: Optional[dict] = Field(None, alias="mini-apps")
    omicron_enabled: bool = Field(..., alias="omicron-enabled")
    save_to_cloud_enabled: bool = Field(..., alias="save-to-cloud-enabled")
    server_suggests_enabled: bool = Field(..., alias="server-suggests-enabled")
    services: dict
    silent_message_delete: bool = Field(..., alias="silent-message-delete")
    smart_reply_stickers_enabled: bool = Field(..., alias="smart-reply-stickers-enabled")
    smart_reply_text_enabled: bool = Field(..., alias="smart-reply-text-enabled")
    snippets_enabled: bool = Field(..., alias="snippets-enabled")
    task_creation_in_chat_enabled: bool = Field(..., alias="task-creation-in-chat-enabled")
    templates_urls: TemplatesUrls = Field(..., alias="templates-urls")
    threads_enabled: bool = Field(..., alias="threads-enabled")
    use_in_house_clients: bool = Field(..., alias="use-in-house-clients")
    user_agreement: UserAgreement = Field(..., alias="user-agreement")
    vk_workmail_discovery_host: str = Field(..., alias="vk-workmail-discovery-host")
    voip_api_version: int = Field(..., alias="voip-api-version")
